/bin/zsh -lc "PYTHONDONTWRITEBYTECODE=1 .venv/bin/python -c 'import sys,csv,re,json,hashlib,copy,io,contextlib,collections,importlib.util
from pathlib import Path
from unittest.mock import patch
spec=importlib.util.spec_from_file_location('\\''v5'\\'',Path('\\''src/sgen010_screen_v5.py'\\''))
v5=importlib.util.module_from_spec(spec); spec.loader.exec_module(v5)
raw={k:list(csv.DictReader(p.open(encoding='\\''utf-8-sig'\\''))) for k,(p,_) in v5.FILES.items()}
M=raw['\\''Model.csv'\\'']; P=raw['\\''passports_model_list_20260921.csv'\\'']; C=raw['\\''lock_s/cohort.csv'\\'']; S=raw['\\''CRISPRScreenMap.csv'\\'']
def run(mut=None,extra_screens=()):
 data=copy.deepcopy(raw)
 if mut: mut(data)
 data['\\''CRISPRScreenMap.csv'\\''].extend({'\\''ScreenID'\\'':'\\''probe'\\'','\\''ModelID'\\'':x} for x in extra_screens)
 captured={}; locals_main={}
 def cap(pairs):
  for p,o in pairs: captured[p.name]=o
 def trace(frame,event,arg):
  if frame.f_code is v5.main.__code__ and event=='\\''return'\\'': locals_main.update(frame.f_locals)
  return trace
 def read(p,drop=()):
  key='\\''lock_s/cohort.csv'\\'' if p.name=='\\''cohort.csv'\\'' else p.name
  return [{k:v for k,v in r.items() if k not in drop} for r in data[key]]
 with patch.object(v5,'\\''rows'\\'',read),patch.object(v5,'\\''write_pair'\\'',cap),contextlib.redirect_stdout(io.StringIO()):
  sys.settrace(trace)
  try: rc=v5.main()
  finally: sys.settrace(None)
 return rc,captured,locals_main
def label(pool,mid):
 return next((k for k,v in pool.items() if k.endswith('\\''_model_ids'\\'') and mid in v),None)

# Independent raw-input recomputation; BFS connected components instead of production DSU.
N=lambda x: '\\'''\\''.join(c for c in (x or '\\'''\\'').upper() if c.isascii() and c.isalnum())
T=lambda x: set(filter(None,(v.strip() for v in (x or '\\'''\\'').split('\\'';'\\''))))
def NUM(x):
 try: return str(int(float(x.strip())))
 except (ValueError,OverflowError):return x.strip()
names=collections.defaultdict(set)
for r in P:
 for n in [r['\\''model_name'\\'']]+re.split('\\''[|;]'\\'',r['\\''synonyms'\\'']):
  if N(n):names[N(n)].add(r['\\''patient_id'\\''])
cmap={r['\\''sample_ID'\\'']:next(iter(names[N(r['\\''sample_ID'\\''])])) for r in C if len(names[N(r['\\''sample_ID'\\''])])==1}
cp=set(cmap.values())
print('\\''Independent Witness A'\\'',len(cmap),len(cp),hashlib.sha256(json.dumps(dict(sorted(cmap.items())),sort_keys=True,separators=('\\'','\\'','\\'':'\\'')).encode()).hexdigest())
index={r:collections.defaultdict(set) for r in ['\\''BROAD_ID'\\'','\\''SIDM'\\'','\\''HCMI'\\'','\\''COSMIC'\\'']}
for r in P:
 for route,col in [('\\''BROAD_ID'\\'','\\''BROAD_ID'\\''),('\\''SIDM'\\'','\\''model_id'\\''),('\\''HCMI'\\'','\\''HCMI'\\''),('\\''COSMIC'\\'','\\''COSMIC_ID'\\'')]:
  for token in T(r[col]):index[route][NUM(token) if route=='\\''COSMIC'\\'' else token].add(r['\\''patient_id'\\''])
A={}; graph=collections.defaultdict(set)
for r in M:
 hits={}
 for route,col in [('\\''BROAD_ID'\\'','\\''ModelID'\\''),('\\''SIDM'\\'','\\''SangerModelID'\\''),('\\''HCMI'\\'','\\''HCMIID'\\''),('\\''COSMIC'\\'','\\''COSMICID'\\'')]:
  pats=set()
  for token in T(r[col]):pats.update(index[route][NUM(token) if route=='\\''COSMIC'\\'' else token])
  if pats:hits[route]=pats
 strong=set().union(*hits.values()) if hits else set()
 nc=names[N(r['\\''CellLineName'\\''])]|names[N(r['\\''StrippedCellLineName'\\''])]
 status='\\''confirmed'\\'' if len(strong)==1 else '\\''conflict'\\'' if strong else '\\''name_only'\\'' if nc else '\\''unresolved'\\''
 a={'\\''strong_routes'\\'':{k:sorted(v) for k,v in sorted(hits.items())},'\\''strong_patients'\\'':sorted(strong),'\\''name_candidates'\\'':sorted(nc),'\\''status'\\'':status,'\\''patient'\\'':next(iter(strong)) if status=='\\''confirmed'\\'' else None}
 A[r['\\''ModelID'\\'']]=a
 dm=('\\''DM'\\'',r['\\''PatientID'\\'']); graph[dm]
 if a['\\''patient'\\'']:
  sidp=('\\''SIDP'\\'',a['\\''patient'\\'']); graph[dm].add(sidp); graph[sidp].add(dm)
component={}; groups=[]
for node in list(graph):
 if node in component:continue
 gid=len(groups); visited={node}; q=[node]
 while q:
  n=q.pop()
  for nxt in graph[n]:
   if nxt not in visited:visited.add(nxt);q.append(nxt)
 for n in visited:component[n]=gid
 groups.append(visited)
badcomps={component[('\\''SIDP'\\'',p)] for p in cp if ('\\''SIDP'\\'',p) in component}
for r in M:
 a=A[r['\\''ModelID'\\'']]
 if cp.intersection(a['\\''strong_patients'\\'']+a['\\''name_candidates'\\'']):badcomps.add(component[('\\''DM'\\'',r['\\''PatientID'\\''])])
screenids={r['\\''ModelID'\\''] for r in S}; byid={r['\\''ModelID'\\'']:r for r in M}
print('\\''Integrity'\\'', '\\''missing_screen_models'\\'',sorted(screenids-set(byid)),'\\''empty_PatientIDs'\\'',sum(not r['\\''PatientID'\\''] for r in M))
buckets={k:[] for k in ['\\''established'\\'','\\''c_overlap'\\'','\\''conflict'\\'','\\''name_only'\\'','\\''unresolved'\\'']}
for mid in screenids:
 r=byid[mid];a=A[mid];gid=component[('\\''DM'\\'',r['\\''PatientID'\\''])]
 b='\\''c_overlap'\\'' if gid in badcomps else '\\''established'\\'' if a['\\''status'\\'']=='\\''confirmed'\\'' else a['\\''status'\\'']
 buckets[b].append(mid)
def summary(ids):
 return {'\\''models'\\'':len(ids),'\\''DepMap_PatientIDs'\\'':len({byid[x]['\\''PatientID'\\''] for x in ids if byid[x]['\\''PatientID'\\'']}),'\\''confirmed_SIDP_patients'\\'':len({A[x]['\\''patient'\\''] for x in ids if A[x]['\\''patient'\\'']}),'\\''linked_patient_components'\\'':len({component[('\\''DM'\\'',byid[x]['\\''PatientID'\\''])] for x in ids})}
print('\\''INDEPENDENT CLASSIFICATION'\\'',json.dumps({k:summary(v) for k,v in buckets.items()},sort_keys=True))
print('\\''ALL TABLE STATUSES'\\'',dict(collections.Counter(a['\\''status'\\''] for a in A.values())))
for mid in ['\\''ACH-000561'\\'','\\''ACH-001131'\\'','\\''ACH-000833'\\'','\\''ACH-000338'\\'','\\''ACH-000498'\\'']:
 print('\\''CASE'\\'',mid,A[mid])
print('\\''NAME ONLY'\\'',buckets['\\''name_only'\\''])
print('\\''CANDIDATE DISAGREEMENTS'\\'',[(x,A[x]) for x in screenids if A[x]['\\''patient'\\''] and set(A[x]['\\''name_candidates'\\''])-{A[x]['\\''patient'\\'']}])
print('\\''ACTUAL CONFLICTS'\\'',[(mid,byid[mid]['\\''CellLineName'\\''],a) for mid,a in A.items() if a['\\''status'\\'']=='\\''conflict'\\''])
rc,out,loc=run()
report=out['\\''screen_v5.json'\\''];pool=out['\\''established_pool_v2.json'\\'']
assert A==loc['\\''all_assign'\\'']
assert {k:summary(v) for k,v in buckets.items()}==report['\\''classification'\\'']
for k,v in buckets.items():assert sorted(v)==pool[k+'\\''_model_ids'\\'']
for f,obj in out.items():print('\\''STORED_EQUALS_REEXECUTION'\\'',f,obj==json.loads(Path('\\''generations/sgen010'\\'',f).read_text()))
print('\\''DIAGNOSTICS'\\'',report['\\''diagnostics'\\''])
print('\\''ORGANOIDS'\\'',report['\\''organoid_subset'\\''])
print('\\''SPEC HASH'\\'',hashlib.sha256(Path('\\''generations/sgen010/SPEC.md'\\'').read_bytes()).hexdigest())
'"

